<p class="small">{{ strtoupper($s['transaction_type']) }} &middot; {{ $s['payment_method'] }}</p>
<table><thead><tr><th>Item</th><th class="qty">Qty</th><th class="right amount">Amount</th></tr></thead><tbody>@foreach($s['lines'] as $line)<tr><td>{{ $line['name'] }}</td><td class="qty">{{ $line['quantity'] }}</td><td class="right amount">{{ number_format($line['base'], 2) }}</td></tr>@endforeach</tbody></table>
<table><tr><td>Net amount</td><td class="right">{{ number_format(array_sum(array_column($s['lines'], 'base')), 2) }}</td></tr><tr><td>PRA Sales Tax</td><td class="right">{{ number_format($s['pra_tax'], 2) }}</td></tr><tr><td>Rounding</td><td class="right">{{ number_format($s['total'] - array_sum(array_column($s['lines'], 'base')) - $s['pra_tax'], 2) }}</td></tr><tr class="total"><td>{{ $s['transaction_type'] === 'return' ? 'RETURN TOTAL' : 'TOTAL' }}</td><td class="right">{{ number_format($s['total'], 2) }}</td></tr></table>
<table class="fiscal"><thead><tr><th>PRA</th><th>FBR DI @if($record->state === 'accepted' && $record->fiscalReference())<img class="brand" src="{{ asset('images/fbr-digital-invoice-logo-print.png') }}" alt="FBR DI logo">@endif</th></tr></thead><tbody><tr><td>{{ $s['pra_status'] ?: 'Not reported' }}<br>@if($s['pra_status'] === 'submitted' && $s['pra_number']){{ $s['pra_number'] }}@endif</td><td>{{ $live ? 'Production' : 'Sandbox' }}: {{ str_replace('_', ' ', strtoupper($record->state)) }}<br>@if($record->state === 'accepted' && $record->fiscalReference())<span data-fbr-sandbox-reference>{{ $record->fiscalReference() }}</span>@endif</td></tr><tr><td>@if($s['pra_status'] === 'submitted' && $s['pra_number'])<img class="qr" src="{{ \App\Support\QrImage::dataUri($s['pra_number'], 5, 4) }}" alt="PRA source QR">@endif</td><td>@if($record->state === 'accepted' && $record->fiscalReference())<img class="qr" src="{{ \App\Support\QrImage::dataUri($record->fiscalReference(), 5, 4) }}" alt="{{ $live ? 'FBR production acknowledgement QR' : 'FBR sandbox acknowledgement QR' }}">@else<span>No accepted FBR {{ $live ? 'production' : 'sandbox' }} reference.<br>No FBR verification QR issued.</span>@endif</td></tr></tbody></table>
